// 2. TRACE EVENT PIPELINE WITH DISTRIBUTED TRACING
class DataQualityPipeline:
  def process_dataset(self, dataset_id, trace_id):
    try:
      span_ingest = tracer.start_span("data_ingestion", trace_id)
      rows = ingest_data(dataset_id)
      span_ingest.add_event("rows_loaded", {count: len(rows)})

      span_check = tracer.start_span("quality_check", trace_id)
      null_count = count_nulls(rows)
      null_ratio = null_count / len(rows)
      span_check.add_event("null_check_result", {
        null_count, null_ratio, rule_id, 
        should_alert: null_ratio >= rule.threshold
      })

      if null_ratio >= rule.threshold:
        span_alert = tracer.start_span("alert_generation", trace_id)
        alert_event = create_alert_event(dataset_id, null_ratio, timestamp.now())
        # Idempotent: include idempotency_key
        alert_event.idempotency_key = hash(dataset_id + rule_id + timestamp.date)

        span_queue = tracer.start_span("alert_enqueue", trace_id)
        try:
          enqueue_alert(alert_event, idempotency_key=alert_event.idempotency_key)
          span_queue.set_status("success")
        except Exception as e:
          span_queue.set_status("failed", {error: str(e)})
          # Send to DLQ with full context
          send_to_dlq(alert_event, trace_id, reason=str(e), retry_count=0)
      else:
        span_check.add_event("alert_not_triggered", {reason: "below_threshold"})
    except Exception as e:
      tracer.record_exception(e, trace_id)
      log("ERROR", {stage: "pipeline", error: str(e), trace_id})
      raise

