    log_entry = {
      timestamp: now(),
      trace_id,
      event_type: "rule_evaluation",
      rule_id,
      dataset_id,
      condition_met: result.triggered,
      metric_value: result.null_ratio,
      threshold: result.threshold,
      decision: "alert_sent" if result.triggered else "no_alert",
      reason: result.reason  // "below_threshold" or error details
    }
    emit_to_log_sink(log_entry)

// 4. HANDLE DEAD LETTER QUEUES WITH REPLAY
class DLQHandler:
  def process_dlq(self):
    for failed_event in dlq.read(batch_size=100):
      log("Processing DLQ event", {event_id: failed_event.id, reason: failed_event.reason})

      // Attempt replay with exponential backoff
      retry_count = failed_event.retry_count
      if retry_count > MAX_RETRIES:
        log("DLQ event exceeded max retries", {event_id, retry_count})
        send_to_dead_letter_sink(failed_event)  // For manual inspection
        continue

      try:
        // Use original trace context for observability
        enqueue_alert(failed_event.alert_event, 
                     idempotency_key=failed_event.idempotency_key,
                     original_trace_id=failed_event.trace_id)
        dlq.acknowledge(failed_event.id)
        metrics.increment("dlq_replay_success")
      except Exception as e:
        failed_event.retry_count += 1
        dlq.requeue(failed_event, 
                   delay=exponential_backoff(retry_count),
                   reason=str(e))
        metrics.increment("dlq_replay_failure")

// 5. IMPLEMENT IDEMPOTENCY FOR ALERT DELIVERY
class IdempotentAlertDelivery:
  def send_alert(self, alert_event, idempotency_key):
    // Check if already processed
    existing = idempotency_cache.get(idempotency_key)
    if existing:
      log("Alert already delivered", {idempotency_key, delivered_at: existing.timestamp})
      return existing.delivery_result

    // Deliver alert
    try:
      delivery_result = deliver_to_channels(alert_event)
      idempotency_cache.set(idempotency_key, {
        timestamp: now(),
        delivery_result,
        ttl: 24_hours
      })
      metrics.increment("alert_delivered")
      return delivery_result
    except Exception as e:
      metrics.increment("alert_delivery_failed", {channel: e.channel})
      raise

