class ObservabilityMetrics:
  def emit_metrics(self, rule_id, dataset_id, null_ratio, triggered):
    // Gauge: actual metric value
    metrics.gauge("data_quality.null_ratio", null_ratio, 
                 {rule_id, dataset_id})

    // Counter: evaluation results
    metrics.increment(
      "data_quality.rule_evaluation",
      {rule_id, dataset_id, result: "alert_triggered" if triggered else "no_alert"}
    )

    // Track pipeline health
    metrics.increment("pipeline.stage_completion", 
                     {stage: "quality_check", success: true})

    // Alert delivery success
    if triggered:
      metrics.increment("alerts.generated", {rule_id})

