# Stream Processing
class AnomalyDetectionJob:
  def process_metrics_stream(self, kafka_stream):
    windowed = kafka_stream.window(TumblingWindow(60_seconds))
    aggregated = windowed.map(aggregate_metrics_by_pipeline_id)

    for metric in aggregated:
      # Rule-based detection
      if metric.row_count < pipeline.expected_min_rows:
        emit_anomaly(severity='high', type='low_row_count', metric=metric)

      if metric.null_percentage > pipeline.null_threshold:
        emit_anomaly(severity='medium', type='high_nulls', metric=metric)

      # Statistical detection (z-score on 7-day window)
      z_score = (metric.value - historical_mean) / historical_std_dev
      if abs(z_score) > 3.0:
        emit_anomaly(severity='medium', type='statistical_outlier', metric=metric)

    store_aggregated_metrics(timeseries_db, metric)

# Alerting Layer
class AlertManager:
  def process_anomalies(self, anomaly_stream):
    for anomaly in anomaly_stream:
      # Deduplication: only alert if not alerted in last 5 minutes
      if not self.recently_alerted(anomaly.pipeline_id, anomaly.type):
        # Query rules to determine channels and recipients
        rule = metadata_store.get_alert_rule(anomaly.pipeline_id, anomaly.type)
        recipients = metadata_store.get_recipients(rule.team_id)

        alert = create_alert(anomaly, recipients, rule.severity)
        self.route_alert(alert)  # Slack, PagerDuty, email, webhook

        # Record alert for dashboard and ACK tracking
        alert_event_log.append(alert)

# API Layer
class QualityMonitoringAPI:
  @endpoint('/api/v1/pipelines/{pipeline_id}/metrics')
  def get_recent_metrics(self, pipeline_id, last_n_minutes=60):
    # Query from time-series cache or DB
    metrics = timeseries_db.query(
      f"SELECT * FROM metrics WHERE pipeline_id={pipeline_id} AND time > now() - {last_n_minutes}m"
    )
    return metrics_to_json(metrics)

  @endpoint('/api/v1/pipelines/{pipeline_id}/anomalies')
  def get_anomalies(self, pipeline_id, unresolved_only=True):
    # Query recent anomalies from cache
    anomalies = redis.get(f'anomalies:{pipeline_id}')
    if unresolved_only:
      anomalies = [a for a in anomalies if not a.resolved]
    return anomalies

  @endpoint('/api/v1/rules', method='POST')
  def create_quality_rule(self, pipeline_id, rule_config):
    # Validate rule syntax, store in metadata
    rule = QualityRule.from_config(rule_config)
    metadata_store.insert_rule(pipeline_id, rule)
    return {"rule_id": rule.id, "status": "created"}

  @endpoint('/api/v1/sla-report')
  def get_sla_report(self, team_id, start_date, end_date):
    # Aggregate SLA status over date range
    report = metadata_store.compute_sla_report(team_id, start_date, end_date)
    return report

